let languageChoice='auto';
try { const saved=localStorage.getItem(languageKey); if(['auto','de','en'].includes(saved))languageChoice=saved; } catch(e) {}
function browserLanguage(){const langs=navigator.languages?.length?navigator.languages:[navigator.language||'en'];return langs[0]?.toLowerCase().startsWith('de')?'de':'en';}
function language(){return languageChoice==='auto'?browserLanguage():languageChoice;}
const ui={
 de:{title:'Charakter-Roulette',filters:'Auswahl',hide:'Filter ausblenden',show:'Filter anzeigen',hint:'Wähle die möglichen Fraktionen, Völker, Klassen und Geschlechter. Die Auswahl bleibt beim Neuladen gespeichert.',factions:'Fraktionen & Völker',classes:'Klassen',gender:'Geschlecht',specs:'Spezialisierungen',all:'Alle auswählen',none:'Alle abwählen',generate:'⚄ Charakter generieren',your:'DEIN CHARAKTER',count:'mögliche Charakterkombinationen',pairs:'Volk-Klasse-Paare',warning:'Keine gültige Kombination ausgewählt.',missing:'Für diese Kombination fehlt ein Charakterbild – Klassen-Icon als Ersatz.',placeholder:'Skyborn: Nachtelfen-Modell als Platzhalter.',male:'Männlich',female:'Weiblich'},
 en:{title:'Character Roulette',filters:'Filters',hide:'Hide filters',show:'Show filters',hint:'Choose the available factions, races, classes, and genders. Your selection is saved when you reload.',factions:'Factions & Races',classes:'Classes',gender:'Gender',specs:'Specializations',all:'Select all',none:'Clear all',generate:'⚄ Generate character',your:'YOUR CHARACTER',count:'possible character combinations',pairs:'race-class pairs',warning:'No valid combination selected.',missing:'No character image for this combination – showing the class icon instead.',placeholder:'Skyborn: Night Elf model used as a placeholder.',male:'Male',female:'Female'}
};
const raceEnglish={human:'Human',dwarf:'Dwarf',nightelf:'Night Elf',gnome:'Gnome','skyborne-alliance':'Skyborn – High Order',orc:'Orc',undead:'Undead',tauren:'Tauren',troll:'Troll','skyborne-horde':'Skyborn – Windshaper'};
const classEnglish={warrior:'Warrior',paladin:'Paladin',hunter:'Hunter',rogue:'Rogue',priest:'Priest',shaman:'Shaman',mage:'Mage',warlock:'Warlock',druid:'Druid'};
function factionName(id){return language()==='de'?(id==='alliance'?'Allianz':'Horde'):(id==='alliance'?'Alliance':'Horde');}
function raceName(id){return language()==='de'?raceLabel[id]:raceEnglish[id];}
function className(id){return language()==='de'?classLabel[id]:classEnglish[id];}
function specName(spec){return language()==='de'?spec[1]:spec[0];}
function t(key){return ui[language()][key];}
const state={races:new Set(Object.keys(valid)),classes:new Set(classes.map(x=>x[0])),bodytypes:new Set(bodytypes.map(x=>x[0])),specs:new Set(Object.entries(specs).flatMap(([c,items])=>items.map((_,i)=>`${c}-${i}`)))};
function raceAssetId(id){
 return id.startsWith('skyborne-')?'skyborne':id==='undead'?'scourge':id;
}
function filterRaceSex(){
 return state.bodytypes.size===1 && state.bodytypes.has('body2')?'female':'male';
}
function updateRaceFilterIcons(){
 document.querySelectorAll('[data-race-icon]').forEach(img=>{
   img.src=`icons/races/race_${raceAssetId(img.dataset.raceIcon)}_${filterRaceSex()}.jpg`;
 });
}
function icon(kind,id,short){
 const wrap=document.createElement('span');wrap.className='glyph';wrap.textContent=short;
 const src=kind==='classes'?`icons/classes/class_${id}.jpg`:kind==='factions'?`icons/${id}.png`:kind==='specs'?`icons/specs/${id}.jpg`:kind==='races'?`icons/races/race_${raceAssetId(id)}_${filterRaceSex()}.jpg`:null;
 if(src){const img=document.createElement('img');img.alt='';img.src=src;if(kind==='races')img.dataset.raceIcon=id;img.addEventListener('load',()=>wrap.replaceWith(img));}
 return wrap;
}
function option(kind,item,iconAsset){const [id,label,abbr]=item;const el=document.createElement('label');el.className='choice';const input=document.createElement('input');input.type='checkbox';input.checked=state[kind].has(id);input.dataset.kind=kind;input.dataset.id=id;input.addEventListener('change',()=>{updateFilter(kind,id,input.checked);syncInputs();refresh();updateRaceFilterIcons();});const text=document.createElement('span');text.className='choice-label';text.textContent=label;el.append(input,icon(kind,iconAsset??id,abbr),text);return el;}
function updateFilter(kind,id,checked){
 if(kind==='classes'){
  if(checked){state.classes.add(id);specs[id].forEach((_,i)=>state.specs.add(`${id}-${i}`));}
  else{state.classes.delete(id);specs[id].forEach((_,i)=>state.specs.delete(`${id}-${i}`));}
 } else if(kind==='specs'){
  if(checked)state.specs.add(id);else state.specs.delete(id);
  const cls=id.slice(0,id.lastIndexOf('-'));
  if(specs[cls].some((_,i)=>state.specs.has(`${cls}-${i}`)))state.classes.add(cls);
  else state.classes.delete(cls);
 }else{if(checked)state[kind].add(id);else state[kind].delete(id);}
}
function normalizeClassSpecs(){for(const [cls,items] of Object.entries(specs)){
 const any=items.some((_,i)=>state.specs.has(`${cls}-${i}`));
 if(any)state.classes.add(cls);else state.classes.delete(cls);
}}
const storageKey='wow-forever-roulette-filters-v3';
const visitedKey='wow-forever-roulette-visited-v2';
function restore(){try{const data=JSON.parse(localStorage.getItem(storageKey)||localStorage.getItem('wow-forever-roulette-filters-v2'));if(!data)return;for(const kind of ['races','classes','bodytypes','specs'])if(Array.isArray(data[kind])){const allowed=new Set(kind==='races'?Object.keys(valid):kind==='classes'?classes.map(x=>x[0]):kind==='specs'?Object.entries(specs).flatMap(([c,items])=>items.map((_,i)=>`${c}-${i}`)):bodytypes.map(x=>x[0]));state[kind]=new Set(data[kind].filter(x=>allowed.has(x)));}normalizeClassSpecs();}catch(e){console.warn('Filter konnten nicht geladen werden',e)}}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(Object.fromEntries(['races','classes','bodytypes','specs'].map(k=>[k,[...state[k]]]))))}catch(e){}}
function render(){const froot=document.getElementById('factions');for(const f of factions){const box=document.createElement('div');box.className='faction '+f.id;const head=document.createElement('label');head.className='factionhead';const cb=document.createElement('input');cb.type='checkbox';cb.dataset.faction=f.id;cb.addEventListener('change',()=>{for(const r of f.races){cb.checked?state.races.add(r[0]):state.races.delete(r[0]);}syncInputs();refresh();updateRaceFilterIcons();});const factionText=document.createElement('span');factionText.dataset.factionLabel=f.id;factionText.textContent=factionName(f.id);head.append(cb,icon('factions',f.id,f.id==='alliance'?'A':'H'),factionText);const list=document.createElement('div');list.className='choices';f.races.forEach(r=>list.append(option('races',r)));box.append(head,list);froot.append(box);}classes.forEach(c=>document.getElementById('classes').append(option('classes',c)));bodytypes.forEach(b=>document.getElementById('bodytypes').append(option('bodytypes',b)));for(const [cls,items] of Object.entries(specs)){const group=document.createElement('div');group.className='spec-group';const title=document.createElement('h4');title.dataset.classTitle=cls;title.textContent=className(cls);group.append(title);items.forEach(([en,de,asset],i)=>{const id=`${cls}-${i}`;const el=option('specs',[id,de,'✦'],asset);group.append(el);});document.getElementById('specs').append(group);}document.getElementById('all').onclick=()=>setAll(true);document.getElementById('none').onclick=()=>setAll(false);refresh();}
function syncInputs(){document.querySelectorAll('input[data-kind]').forEach(i=>{i.checked=state[i.dataset.kind].has(i.dataset.id)});}
function updateEmptyFilters(){
 const categories=[['factions',state.races.size===0],['classes',state.classes.size===0],['bodytypes',state.bodytypes.size===0],['specs',state.specs.size===0]];
 for(const [id,empty] of categories){
  const group=document.getElementById(id)?.closest('.group');
  if(group)group.classList.toggle('filter-empty',empty);
 }
 document.getElementById('filter-panel').classList.toggle('has-empty-filter',categories.some(([,empty])=>empty));
}
function refresh(){updateEmptyFilters();for(const f of factions){const i=document.querySelector(`[data-faction="${f.id}"]`);const n=f.races.filter(r=>state.races.has(r[0])).length;i.checked=n===f.races.length;i.indeterminate=n>0&&n<f.races.length;}let pairs=0;for(const r of state.races)for(const c of state.classes)if(valid[r]?.includes(c))pairs++;const total=[...state.races].reduce((n,r)=>n+[...state.classes].filter(c=>valid[r]?.includes(c)).reduce((m,c)=>m+specs[c].filter((_,i)=>state.specs.has(`${c}-${i}`)).length,0),0)*state.bodytypes.size;document.getElementById('count').textContent=`${total} ${t('count')} (${pairs} ${t('pairs')})`;document.getElementById('warning').textContent=total===0?t('warning'):'';persist();document.getElementById('generate').disabled=total===0;}
function setAll(yes){for(const [kind,ids] of [['races',Object.keys(valid)],['classes',classes.map(x=>x[0])],['bodytypes',bodytypes.map(x=>x[0])],['specs',Object.entries(specs).flatMap(([c,items])=>items.map((_,i)=>`${c}-${i}`))]]){state[kind].clear();if(yes)ids.forEach(x=>state[kind].add(x));}syncInputs();refresh();updateRaceFilterIcons();}
