const classColors={
 warrior:'#C79C6E',paladin:'#F58CBA',hunter:'#ABD473',rogue:'#FFF569',
 priest:'#FFFFFF',shaman:'#0070DE',mage:'#3FC7EB',warlock:'#8788EE',druid:'#FF7D0A'
};
const pick=a=>a[Math.floor(Math.random()*a.length)];
function firstName(race,body){const sex=body==='body1'?'male':'female';const data=syllables[race][sex];for(let i=0;i<100;i++){const n=pick(data[0])+pick(data[1])+(Math.random()<.35?pick(data[2].filter(s=>s.length>=2)):'');if(n.length<=12&&n.length>=4&&!/(.{2})\1/i.test(n))return n;}return 'Bromgar'}
function lastName(race,cls,lang=language()){const r=raceWords[lang][race],c=classWords[lang][cls];const first=[...r.first,...c.first],last=[...r.last,...c.last];for(let i=0;i<100;i++){const a=pick(first),b=pick(last),n=a+b;if(n.length>(lang==='en'?16:12)||a.toLowerCase()===b.toLowerCase())continue;if(/^(schwertschild|schildschwert|hornhuf|hufhorn)$/i.test(n))continue;return n;}return lang==='de'?'Sturmwind':'Stormwind'}
// Namen innerhalb eines Browser-Tabs auch bei F5 nicht sofort wiederholen.
const recentNameKey='wow-forever-roulette-recent-names-v1';
const recentNameLimit=60;
let recentNames=[];
try { const saved=JSON.parse(sessionStorage.getItem(recentNameKey)||'[]'); if(Array.isArray(saved))recentNames=saved.filter(x=>typeof x==='string').slice(-recentNameLimit); } catch(e) {}
function uniqueName(race,body,cls,lang=language()){
 let name='';
 for(let attempt=0;attempt<500;attempt++){
  name=firstName(race,body)+' '+lastName(race,cls,lang);
  if(!recentNames.includes(name))break;
 }
 recentNames.push(name);
 if(recentNames.length>recentNameLimit)recentNames.shift();
 try { sessionStorage.setItem(recentNameKey,JSON.stringify(recentNames)); } catch(e) {}
 return name;
}
function combinations(){const list=[];for(const r of state.races)for(const c of state.classes)if(valid[r]?.includes(c))for(const b of state.bodytypes)for(let i=0;i<specs[c].length;i++)if(state.specs.has(`${c}-${i}`))list.push({race:r,cls:c,body:b,spec:specs[c][i]});return list}
const raceLabel=Object.fromEntries(factions.flatMap(f=>f.races.map(r=>[r[0],r[1]])));
const classLabel=Object.fromEntries(classes.map(c=>[c[0],c[1]]));
const factionLabel=Object.fromEntries(factions.flatMap(f=>f.races.map(r=>[r[0],f.label])));
let currentCharacter=null;
function generate(scroll=false){
 const possibilities=combinations();if(!possibilities.length)return;
 const {race,cls,body,spec}=pick(possibilities);
 const name=uniqueName(race,body,cls);
 const first=name.split(' ')[0];currentCharacter={race,cls,body,spec,first,surname:name.slice(first.length+1),lang:language(),surnames:{[language()]:name.slice(first.length+1)}};
 showCharacter(currentCharacter,scroll);
}
function showCharacter(character,scroll=false){
 const {race,cls,body,spec}=character;
 const name=character.first+' '+character.surname;
 document.getElementById('character-name').textContent=name;
 const result=document.getElementById('result');
 result.dataset.faction=factions[0].races.some(r=>r[0]===race)?'alliance':'horde';
 result.style.setProperty('--class-color',classColors[cls]||'#f2ce86');
 const meta=document.getElementById('character-meta');meta.replaceChildren();
 const factionId=result.dataset.faction;
 const add=(kind,id,label)=>{meta.append(icon(kind,id,label.slice(0,2)));meta.append(document.createTextNode(' '+label+' · '));};
 add('factions',factionId,factionName(factionId));
 const raceResultIcon=document.createElement('img');
 raceResultIcon.src=`icons/races/race_${raceAssetId(race)}_${body==='body1'?'male':'female'}.jpg`;
 raceResultIcon.alt='';
 meta.append(raceResultIcon,document.createTextNode(' '+raceName(race)+' · '+(body==='body1'?t('male'):t('female'))+' · '));
 add('classes',cls,className(cls));
 meta.append(icon('specs',spec[2],'✦'),document.createTextNode(' '+specName(spec)));
 const badges=document.getElementById('stage-badges');badges.replaceChildren();
 badges.append(icon('classes',cls,className(cls).slice(0,2)),icon('specs',spec[2],'✦'));
 const img=document.getElementById('character-image');
 const modelRace=race.startsWith('skyborne-')?'nightelf':race;
 const sex=body==='body1'?'male':'female';
 const path=`images/characters/${cls}-${modelRace}-${sex}.webp`;
 img.onerror=()=>{img.onerror=null;img.src=`icons/classes/class_${cls}.jpg`;document.getElementById('image-notice').textContent=t('missing');};
 img.src=path;img.alt=name+' – '+raceName(race)+' '+className(cls);
 document.getElementById('image-notice').textContent=race.startsWith('skyborne-')?t('placeholder'):'';
 if(scroll&&window.matchMedia('(max-width:850px)').matches)requestAnimationFrame(()=>requestAnimationFrame(scrollToResult));
}
function scrollToResult(){const button=document.getElementById('generate');const target=document.getElementById('result');const y=target.getBoundingClientRect().top+window.scrollY-button.getBoundingClientRect().height-12;window.scrollTo({top:y,behavior:'smooth'});}
// Der erste Besuch zeigt die Filter; bei späteren Besuchen sind sie zunächst eingeklappt.
// Ein manueller Wechsel bleibt innerhalb des aktuellen Seitenaufrufs erhalten.
const filterPanel=document.getElementById('filter-panel');
const filterContent=document.getElementById('filter-content');
const filterToggle=document.getElementById('toggle-filters');
const returningVisit=(()=>{try{return localStorage.getItem(visitedKey)==='yes'}catch(e){return false}})();
function setFiltersOpen(open){
  filterContent.hidden=!open;
  filterPanel.classList.toggle('is-collapsed',!open);
  filterToggle.setAttribute('aria-expanded',String(open));
  filterToggle.innerHTML=(open?t('hide'):t('show'))+' <span aria-hidden="true">'+(open?'▴':'▾')+'</span>'; 
}
setFiltersOpen(!returningVisit);
filterToggle.addEventListener('click',()=>setFiltersOpen(filterContent.hidden));
function translateUI(){
 document.documentElement.lang=language();
 document.title=t('title')+' · World of Warcraft Forever';
 for(const [id,key] of Object.entries({'page-title':'title','filters-heading':'filters','filters-hint':'hint','factions-heading':'factions','classes-heading':'classes','gender-heading':'gender','specs-heading':'specs','all':'all','none':'none','generate':'generate','your-character':'your'})){
  const el=document.getElementById(id);if(el)el.textContent=t(key);
 }
 document.querySelectorAll('[data-faction-label]').forEach(el=>el.textContent=factionName(el.dataset.factionLabel));
 document.querySelectorAll('input[data-kind]').forEach(el=>{
  const kind=el.dataset.kind,id=el.dataset.id;
  let label='';
  if(kind==='races')label=raceName(id);
  else if(kind==='classes')label=className(id);
  else if(kind==='bodytypes')label=id==='body1'?t('male'):t('female');
  else if(kind==='specs'){const cls=id.slice(0,id.lastIndexOf('-')),i=Number(id.slice(id.lastIndexOf('-')+1));label=specName(specs[cls][i]);}
  const target=el.closest('label')?.querySelector('.choice-label');if(target)target.textContent=label;
 });
 document.querySelectorAll('[data-class-title]').forEach(el=>el.textContent=className(el.dataset.classTitle));
 setFiltersOpen(!filterContent.hidden);
 refresh();
 if(currentCharacter){
  if(currentCharacter.lang!==language()){
   // Reuse the existing first name and choose a surname from the newly selected language.
   currentCharacter.surname=currentCharacter.surnames[language()]??lastName(currentCharacter.race,currentCharacter.cls,language());
   currentCharacter.surnames[language()]=currentCharacter.surname;
   currentCharacter.lang=language();
  }
  showCharacter(currentCharacter);
 }
}
const languageSelect=document.getElementById('language-select');
languageSelect.value=languageChoice;
languageSelect.addEventListener('change',()=>{
 languageChoice=languageSelect.value;
 try{localStorage.setItem(languageKey,languageChoice);}catch(e){}
 translateUI();
});
restore();render();translateUI();
document.getElementById('generate').addEventListener('click',()=>{setFiltersOpen(false);generate(true);});
const returning=returningVisit;
try{localStorage.setItem(visitedKey,'yes')}catch(e){}
generate(false);
if(returning&&window.matchMedia('(max-width:850px)').matches){if('scrollRestoration' in history)history.scrollRestoration='manual';window.addEventListener('load',()=>setTimeout(scrollToResult,80),{once:true})}

